const cmds = [
  ["verify", "python3 -B .artifacts/i18n/repair-w47a-20260927/verify_translation_diff.py"],
  ["lint", "python3 -B tools/i18n lint --strict"],
  ["diffcheck", "git diff --check"]
];
const results = await Promise.all(cmds.map(async ([name, cmd]) => {
  const r = await tools.exec_command({
    cmd,
    workdir: "/workspace/tome4-chinese-translation",
    yield_time_ms: 30000,
    max_output_tokens: 20000,
    sandbox_permissions: "require_escalated",
    justification: "允许我执行用户指定的有界差异校验、strict lint 和 git diff --check 吗？"
  });
  return {name, ...r};
}));
for (const r of results) {
  text(`===== ${r.name} =====\nexit_code=${r.exit_code ?? "running"}\n${r.output}`);
  if (r.session_id) text(`session_id=${r.session_id}`);
}
